import json, subprocess, sys

GATEWAY = "/workspace/submission/gateway.py"

def run(batch):
    data = json.dumps(batch).encode()
    p = subprocess.run([sys.executable, "-I", "-B", GATEWAY],
                       input=data, capture_output=True)
    if p.returncode != 0:
        raise RuntimeError("exit %d stderr=%s" % (p.returncode, p.stderr[:500]))
    out = json.loads(p.stdout)
    assert set(out.keys()) == {"results"}, out.keys()
    return out["results"]

BASE = {
    "directory": {
        "sip:ember@studio.test": ["sip:e1@alias.studio.test", "tel:+12025550121"],
        "sip:desk@sales.test": ["tel:+12025550122"],
    },
    "accounts": {
        "session-k": {"primary": "sip:ember@studio.test", "allow": ["sip:desk@sales.test"]},
    },
    "gateways": {
        "edge": {"local_domains": ["studio.test", "sales.test"], "peers": {}},
        "inside": {"local_domains": [], "peers": {"edge": ["studio.test", "sales.test"]}},
        "narrow": {"local_domains": ["studio.test"], "peers": {"edge": ["sales.test"]}},
    },
}

def batch(jobs, **over):
    b = json.loads(json.dumps(BASE))
    b["jobs"] = jobs
    b.update(over)
    return b

def job(gw="edge", ingress=None, trusted=True, raw=None, source=None):
    j = {"gateway": gw,
         "ingress": ingress or {"kind": "local", "subject": "session-k"},
         "trusted_out": trusted}
    if source is not None:
        j["source"] = source
    else:
        j["raw"] = raw
    return j

def req(method="MESSAGE", ruri="sip:inbox@relay.test", frm="<sip:ember@studio.test>;tag=q7",
        to="<sip:inbox@relay.test>", callid="sample-73", cseq="0009", extra=(),
        body="hello", ctype="text/plain", cl=None):
    lines = ["%s %s SIP/2.0" % (method, ruri),
             "From: " + frm,
             "To: " + to,
             "Call-ID: " + callid,
             "CSeq: %s %s" % (cseq, method)]
    lines += list(extra)
    if ctype is not None:
        lines.append("Content-Type: " + ctype)
    if cl is None:
        cl = str(len(body))
    lines.append("Content-Length: " + cl)
    return "\r\n".join(lines) + "\r\n\r\n" + body

FAILS = []
COUNT = 0

def check(name, results, expected):
    global COUNT
    COUNT += 1
    if results != expected:
        FAILS.append((name, results, expected))
        print("FAIL", name)
        print("  got:     ", json.dumps(results))
        print("  expected:", json.dumps(expected))
    else:
        print("ok  ", name)

def rej(reason):
    return {"status": "reject", "reason": reason}
PYEOF
